#include <bits/stdc++.h>
using namespace std;

int a, b, c, d;

int main() {
    scanf("%02d:%02d%02d:%02d", &a, &b, &c, &d);
    if (c == 0)
        printf("00:%02d", d - b);
    else {
        c--;
        d += 60;
        printf("%02d:%02d", d / 60 + c - a, d % 60);
    }
    return 0;
}

